    (new ESP3TransportArbiter(200))->ReceiveData(json_encode(['DataID'=>'{018EF6B5-AB94-40C6-AA53-46943E824ACF}','Buffer'=>'55002100022600020B01000206030001020304454F0103474154455741594354524C00000000007F']));
