    (new ESP3TransportArbiter(200))->ReceiveData(json_encode(['DataID'=>'{018EF6B5-AB94-40C6-AA53-46943E824ACF}','Buffer'=>'5500050102DB00FFC2F780084B']));
    $m->ProcessProductWorkflow();
};
$read($m);$s=json_decode($m->GetProductSnapshot(),true);
$check($s['hardware']['baseID']==='FFC2F780'&&$s['gateway']['master']==='FFC2F700','Real adapter parser keeps hardware and Master independent');
