$check(json_decode($GLOBALS['egmTest']['instances'][101]['buffers']['ProductFlow'],true)['phase']==='TARGET_STALE','TTL stays 60 seconds; UI validation expires without automatic refresh');
$check(count($GLOBALS['egmTest']['sent'])===$before,'Expiry never creates reads, transactions or writes');
echo 'PASS: '.$passed.' B8.2 module/callback assertions'.PHP_EOL;
